"use client"

import * as React from "react"
import type { SearchEvent, SearchHit } from "@/lib/jev-search-core"

export type SearchPhase = "idle" | "lexical" | "judging" | "done" | "error"

export interface UseJevSearchOptions {
  /** Route that serves createJevSearchHandler. Default "/api/jev-search". */
  endpoint?: string
  /** Debounce in ms before hitting the endpoint. Lexical results are cached so 0 feels fine. Default 60. */
  debounceMs?: number
  minLength?: number
}

export interface JevSearchState {
  query: string
  setQuery: (q: string) => void
  hits: SearchHit[]
  /** The keyword pass on its own, before Jev spoke. Handy for before/after views. */
  lexicalHits: SearchHit[]
  /** The re-ranked list, or undefined until Jev answers. */
  jevHits?: SearchHit[]
  phase: SearchPhase
  /** True once the visible hits are Jev-ranked (not just lexical). */
  judged: boolean
  lexicalMs?: number
  jevMs?: number
  judgedCount?: number
  /** Input tokens billed for this query. */
  inputTokens?: number
  answerable?: number
  model?: string
  cached?: boolean
  error?: string
  reset: () => void
}

interface Entry {
  lexical?: Extract<SearchEvent, { type: "lexical" }>
  jev?: Extract<SearchEvent, { type: "jev" }>
  error?: string
}

export function useJevSearch(options: UseJevSearchOptions = {}): JevSearchState {
  const { endpoint = "/api/jev-search", debounceMs = 60, minLength = 1 } = options
  const [query, setQuery] = React.useState("")
  const [entry, setEntry] = React.useState<Entry>({})
  const [phase, setPhase] = React.useState<SearchPhase>("idle")
  const cache = React.useRef(new Map<string, Entry>())
  const controller = React.useRef<AbortController | null>(null)

  React.useEffect(() => {
    const q = query.trim()
    controller.current?.abort()
    if (q.length < minLength) {
      setEntry({})
      setPhase("idle")
      return
    }
    const key = q.toLowerCase()
    const hit = cache.current.get(key)
    if (hit?.jev) {
      setEntry(hit)
      setPhase("done")
      return
    }
    if (hit?.lexical) {
      setEntry(hit)
      setPhase("judging")
    }

    const ac = new AbortController()
    controller.current = ac
    const timer = setTimeout(async () => {
      const url = `${endpoint}?q=${encodeURIComponent(q)}`
      try {
        const res = await fetch(url, { signal: ac.signal })
        if (!res.ok || !res.body) throw new Error(`search endpoint responded ${res.status}`)
        const reader = res.body.getReader()
        const decoder = new TextDecoder()
        let buffer = ""
        const current: Entry = { ...(cache.current.get(key) ?? {}) }
        const apply = (line: string) => {
          if (!line.trim()) return
          const ev = JSON.parse(line) as SearchEvent
          if (ev.type === "lexical") {
            current.lexical = ev
            setPhase("judging")
          } else if (ev.type === "jev") {
            current.jev = ev
            setPhase("done")
          } else {
            current.error = ev.message
            setPhase("error")
          }
          cache.current.set(key, { ...current })
          if (!ac.signal.aborted) setEntry({ ...current })
        }
        while (true) {
          const { value, done } = await reader.read()
          if (done) break
          buffer += decoder.decode(value, { stream: true })
          let nl: number
          while ((nl = buffer.indexOf("\n")) >= 0) {
            apply(buffer.slice(0, nl))
            buffer = buffer.slice(nl + 1)
          }
        }
        if (buffer.trim()) apply(buffer)
      } catch (err) {
        if ((err as Error).name === "AbortError") return
        setEntry((e) => ({ ...e, error: (err as Error).message }))
        setPhase("error")
      }
    }, debounceMs)
    return () => {
      clearTimeout(timer)
      ac.abort()
    }
  }, [query, endpoint, debounceMs, minLength])

  const hits = entry.jev?.hits ?? entry.lexical?.hits ?? []
  return {
    query,
    setQuery,
    hits,
    lexicalHits: entry.lexical?.hits ?? [],
    jevHits: entry.jev?.hits,
    phase,
    judged: Boolean(entry.jev),
    lexicalMs: entry.lexical?.tookMs,
    jevMs: entry.jev?.tookMs,
    judgedCount: entry.jev?.judged,
    inputTokens: entry.jev?.inputTokens,
    answerable: entry.jev?.answerable,
    model: entry.jev?.model,
    cached: entry.jev?.cached,
    error: entry.error,
    reset: () => {
      setQuery("")
      setEntry({})
      setPhase("idle")
    },
  }
}

/**
 * jev-search — shared types and the lexical first pass.
 *
 * This file is used on both the client (highlighting) and the server
 * (candidate selection). It has no dependencies.
 */

export interface SearchDocument {
  /** Stable id, used as the key in Jev questions. Keep it short. */
  id: string
  title: string
  /** Where the result links to. */
  url: string
  description?: string
  /** Body text. Only the first `excerptLength` chars are sent to Jev. */
  content?: string
  /** Group label shown in the results list, e.g. "Docs", "Blog", "API". */
  section?: string
  keywords?: string[]
}

/** What the server sends back for each hit. Content never leaves the server. */
export interface SearchHit {
  id: string
  title: string
  url: string
  description?: string
  section?: string
  /** Lexical score (relative, unbounded). */
  score: number
  /** Jev's calibrated 0–1 answer to "is this what the user wants?". */
  relevance?: number
  /** Jev's share of "best single answer" probability across the candidates. */
  probability?: number
  /** Query terms that matched, for highlighting. */
  terms: string[]
}

export type SearchEvent =
  | { type: "lexical"; query: string; hits: SearchHit[]; tookMs: number }
  | {
      type: "jev"
      query: string
      hits: SearchHit[]
      tookMs: number
      model: string
      judged: number
      /** Input tokens billed for this query. */
      inputTokens: number
      /** Jev's belief that at least one candidate answers the query. */
      answerable: number
      cached: boolean
    }
  | { type: "error"; query: string; message: string }

const STOP = new Set([
  "a", "an", "and", "are", "as", "at", "be", "by", "can", "do", "does", "for",
  "from", "how", "i", "in", "is", "it", "my", "of", "on", "or", "the", "to",
  "what", "with", "you", "your",
])

/** A very small stemmer: enough for "tickets", "connecting" and "judged" to meet in the middle. */
export function stem(token: string): string {
  if (token.length <= 4) return token
  return token.replace(/(ing|ed|es|ly|s)$/, (m) => (token.length - m.length >= 4 ? "" : m))
}

export function tokenize(text: string): string[] {
  return text
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .split(/[^a-z0-9_]+/)
    .filter((t) => t.length > 0)
    .map(stem)
}

/** Query tokens: stop words dropped unless the query is nothing but stop words. */
export function queryTerms(query: string): string[] {
  const all = tokenize(query)
  const kept = all.filter((t) => !STOP.has(t))
  return kept.length > 0 ? kept : all
}

interface IndexedDocument {
  doc: SearchDocument
  title: string[]
  keywords: string[]
  description: string[]
  content: string[]
  titleText: string
  titleJoined: string
  bodyText: string
}

export interface LexicalIndex {
  docs: IndexedDocument[]
}

export function buildIndex(documents: SearchDocument[]): LexicalIndex {
  return {
    docs: documents.map((doc) => ({
      doc,
      title: tokenize(doc.title),
      keywords: tokenize((doc.keywords ?? []).join(" ")),
      description: tokenize(doc.description ?? ""),
      content: tokenize(doc.content ?? ""),
      titleText: doc.title.toLowerCase(),
      titleJoined: tokenize(doc.title).join(""),
      bodyText: `${doc.description ?? ""}\n${doc.content ?? ""}`.toLowerCase(),
    })),
  }
}

/** Damerau–Levenshtein distance capped at 1: true when a and b differ by one edit. */
function withinOneEdit(a: string, b: string): boolean {
  if (a === b) return true
  const la = a.length
  const lb = b.length
  if (Math.abs(la - lb) > 1) return false
  let i = 0
  while (i < la && i < lb && a[i] === b[i]) i++
  if (la === lb) {
    // substitution or transposition
    if (a.slice(i + 1) === b.slice(i + 1)) return true
    return a[i] === b[i + 1] && a[i + 1] === b[i] && a.slice(i + 2) === b.slice(i + 2)
  }
  // insertion / deletion
  return la > lb ? a.slice(i + 1) === b.slice(i) : a.slice(i) === b.slice(i + 1)
}

const WEIGHTS = {
  titleExact: 10,
  titlePrefix: 6,
  titleFuzzy: 4,
  keywordExact: 7,
  keywordPrefix: 4,
  descriptionExact: 3,
  descriptionPrefix: 2,
  contentExact: 1,
  contentPrefix: 0.4,
  titlePhrase: 12,
  bodyPhrase: 4,
} as const

function fieldScore(tokens: string[], term: string, exact: number, prefix: number, fuzzy = 0): number {
  let best = 0
  let hits = 0
  for (const t of tokens) {
    if (t === term) {
      best = Math.max(best, exact)
      hits++
    } else if (t.startsWith(term)) {
      best = Math.max(best, prefix)
      hits++
    } else if (fuzzy > 0 && term.length >= 5 && withinOneEdit(t, term)) {
      best = Math.max(best, fuzzy)
      hits++
    }
  }
  if (best === 0) return 0
  // A little extra for repeated hits, with quickly diminishing returns.
  return best + Math.min(hits - 1, 3) * best * 0.1
}

export interface LexicalOptions {
  limit?: number
}

/**
 * Rank documents for a query with weighted field matching, prefix matching and
 * one-edit typo tolerance on titles. Fast enough to run on every keystroke for
 * a few thousand documents.
 */
export function lexicalSearch(index: LexicalIndex, query: string, options: LexicalOptions = {}): SearchHit[] {
  const limit = options.limit ?? 20
  const terms = queryTerms(query)
  if (terms.length === 0) return []
  const phrase = query.trim().toLowerCase()

  const scored: { hit: SearchHit; matched: number }[] = []
  for (const d of index.docs) {
    let score = 0
    let matched = 0
    const matchedTerms: string[] = []
    for (const term of terms) {
      let s =
        fieldScore(d.title, term, WEIGHTS.titleExact, WEIGHTS.titlePrefix, WEIGHTS.titleFuzzy) +
        fieldScore(d.keywords, term, WEIGHTS.keywordExact, WEIGHTS.keywordPrefix, WEIGHTS.titleFuzzy) +
        fieldScore(d.description, term, WEIGHTS.descriptionExact, WEIGHTS.descriptionPrefix, WEIGHTS.descriptionPrefix) +
        fieldScore(d.content, term, WEIGHTS.contentExact, WEIGHTS.contentPrefix)
      // "quickstrat" → "quick start": one edit away from the title with its spaces removed.
      if (s === 0 && term.length >= 6 && withinOneEdit(term, d.titleJoined)) s = WEIGHTS.titleFuzzy
      if (s > 0) {
        matched++
        matchedTerms.push(term)
        score += s
      }
    }
    if (matched === 0) continue
    // Reward documents that match more of the query.
    score *= matched / terms.length
    if (phrase.length >= 3 && terms.length > 1) {
      if (d.titleText.includes(phrase)) score += WEIGHTS.titlePhrase
      else if (d.bodyText.includes(phrase)) score += WEIGHTS.bodyPhrase
    }
    // Mild length normalisation so long pages do not win on volume alone.
    score /= 1 + Math.log1p(d.content.length) / 12
    scored.push({
      matched,
      hit: {
        id: d.doc.id,
        title: d.doc.title,
        url: d.doc.url,
        description: d.doc.description,
        section: d.doc.section,
        score,
        terms: matchedTerms,
      },
    })
  }
  scored.sort((a, b) => b.hit.score - a.hit.score || a.hit.title.localeCompare(b.hit.title))
  return scored.slice(0, limit).map((s) => s.hit)
}

/** Split text into [plain, match, plain, match…] segments for highlighting. */
export function highlightSegments(text: string, terms: string[]): { text: string; match: boolean }[] {
  if (!text || terms.length === 0) return [{ text, match: false }]
  const escaped = terms
    .filter((t) => t.length > 0)
    .sort((a, b) => b.length - a.length)
    .map((t) => t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"))
  if (escaped.length === 0) return [{ text, match: false }]
  const re = new RegExp(`(${escaped.join("|")})`, "gi")
  const out: { text: string; match: boolean }[] = []
  let last = 0
  for (const m of text.matchAll(re)) {
    const i = m.index ?? 0
    if (i > last) out.push({ text: text.slice(last, i), match: false })
    out.push({ text: m[0], match: true })
    last = i + m[0].length
  }
  if (last < text.length) out.push({ text: text.slice(last), match: false })
  return out
}

/**
 * jev-search — server side.
 *
 * Runs the lexical first pass over your index, then asks TypeSafe's Jev model
 * to judge the top candidates against the query. Jev returns a calibrated
 * relevance for every candidate in one request, so a query costs one round
 * trip and a few hundred input tokens.
 *
 * Works anywhere the Fetch API exists: Next.js route handlers, Remix, Hono,
 * Bun, Deno, Cloudflare Workers.
 */
import { buildIndex, lexicalSearch, type LexicalIndex, type SearchDocument, type SearchEvent, type SearchHit } from "./jev-search-core"

export interface JevSearchOptions {
  documents: SearchDocument[]
  /** Defaults to process.env.TYPESAFE_API_KEY. */
  apiKey?: string
  /** Defaults to process.env.TYPESAFE_API_URL or https://api.typesafe.ai/v1/systemone. */
  apiUrl?: string
  /** Defaults to "jev-latest". */
  model?: string
  /** How many lexical hits Jev judges. Accuracy plateaus around 20. Default 20. */
  candidates?: number
  /** Hits below this relevance are dropped once Jev has spoken. Default 0.15. */
  threshold?: number
  /** Characters of body text sent to Jev per candidate. Default 320. */
  excerptLength?: number
  /** Number of queries kept in the in-memory cache. Default 1000. */
  cacheSize?: number
  /** Abort the Jev call after this long and fall back to lexical order. Default 4000. */
  timeoutMs?: number
  /** Blend between Jev's per-page relevance and its "best answer" share. Default 0.75 (mostly relevance). */
  relevanceWeight?: number
}

export interface JevRanking {
  hits: SearchHit[]
  model: string
  judged: number
  /** Input tokens billed for this query. Output tokens are free. */
  inputTokens: number
  answerable: number
  tookMs: number
  cached: boolean
}

interface TypeSafeAnswer {
  type: string
  noul?: number
  choice?: string
  probabilities?: Record<string, number>
  confidence?: number
}

interface TypeSafeResponse {
  model: string
  answers: Record<string, TypeSafeAnswer>
  usage?: { input_tokens: number; output_tokens: number }
}

class LRU<V> {
  private map = new Map<string, V>()
  constructor(private max: number) {}
  get(key: string): V | undefined {
    const v = this.map.get(key)
    if (v !== undefined) {
      this.map.delete(key)
      this.map.set(key, v)
    }
    return v
  }
  set(key: string, value: V) {
    this.map.delete(key)
    this.map.set(key, value)
    if (this.map.size > this.max) {
      const oldest = this.map.keys().next().value
      if (oldest !== undefined) this.map.delete(oldest)
    }
  }
}

export function createJevSearch(options: JevSearchOptions) {
  const {
    documents,
    model = "jev-latest",
    candidates: candidateCount = 20,
    threshold = 0.15,
    excerptLength = 320,
    cacheSize = 1000,
    timeoutMs = 4000,
    relevanceWeight = 0.75,
  } = options
  const apiKey = options.apiKey ?? process.env.TYPESAFE_API_KEY
  const apiUrl = options.apiUrl ?? process.env.TYPESAFE_API_URL ?? "https://api.typesafe.ai/v1/systemone"

  const index: LexicalIndex = buildIndex(documents)
  const byId = new Map(documents.map((d) => [d.id, d]))
  const cache = new LRU<Omit<JevRanking, "cached">>(cacheSize)

  function normalize(query: string): string {
    return query.trim().replace(/\s+/g, " ").toLowerCase()
  }

  function lexical(query: string, limit = 20): SearchHit[] {
    return lexicalSearch(index, query, { limit })
  }

  async function judge(query: string, hits: SearchHit[]): Promise<JevRanking> {
    const key = `${model}\u0000${normalize(query)}`
    const cached = cache.get(key)
    if (cached) return { ...cached, cached: true }
    if (!apiKey) throw new Error("jev-search: TYPESAFE_API_KEY is not set")

    const started = performance.now()
    const cands = hits.slice(0, candidateCount)
    if (cands.length === 0) {
      return { hits: [], model, judged: 0, inputTokens: 0, answerable: 0, tookMs: 0, cached: false }
    }

    const state = {
      query,
      candidates: cands.map((h, i) => {
        const doc = byId.get(h.id)
        return {
          id: `c${i + 1}`,
          section: h.section,
          title: h.title,
          description: h.description,
          excerpt: doc?.content?.slice(0, excerptLength),
        }
      }),
    }
    const criteria: Record<string, string> = {}
    const questions: Record<string, unknown> = {}
    cands.forEach((h, i) => {
      const id = `c${i + 1}`
      criteria[id] = `${h.title}${h.description ? ` — ${h.description}` : ""}`
      questions[id] = {
        type: "noul",
        instructions: `The user typed the search query above into a site search box. Is candidate ${id} ("${h.title}") a page they would be glad to land on for that query?`,
        criteria: {
          true: "The page answers, covers or is clearly about what the query is asking for",
          false: "The page is off-topic, or only shares a word or two with the query",
        },
      }
    })
    questions.best = {
      type: "choice",
      instructions: "Which candidate page best answers the user's search query?",
      criteria,
    }
    questions.answerable = {
      type: "noul",
      instructions: "Does at least one candidate page answer the user's search query?",
    }

    const payload = JSON.stringify({ state, model, questions })
    let body: TypeSafeResponse | undefined
    let lastError: Error | undefined
    // 401 and 422 are our fault; anything else gets two quick retries.
    for (let attempt = 0; attempt < 3 && !body; attempt++) {
      if (attempt > 0) await new Promise((r) => setTimeout(r, 150 * attempt * attempt))
      const controller = new AbortController()
      const timer = setTimeout(() => controller.abort(), timeoutMs)
      try {
        const res = await fetch(apiUrl, {
          method: "POST",
          headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json" },
          body: payload,
          signal: controller.signal,
        })
        if (res.ok) {
          body = (await res.json()) as TypeSafeResponse
        } else {
          const text = await res.text().catch(() => "")
          lastError = new Error(`jev-search: TypeSafe responded ${res.status} ${text.slice(0, 200)}`)
          if (res.status === 401 || res.status === 422) break
        }
      } catch (err) {
        lastError = err as Error
      } finally {
        clearTimeout(timer)
      }
    }
    if (!body) throw lastError ?? new Error("jev-search: TypeSafe call failed")
    const best = body.answers.best?.probabilities ?? {}

    const ranked: SearchHit[] = cands.map((h, i) => {
      const id = `c${i + 1}`
      const relevance = body.answers[id]?.noul ?? 0
      const probability = best[id] ?? 0
      return { ...h, relevance, probability }
    })
    const blended = (h: SearchHit) => relevanceWeight * (h.relevance ?? 0) + (1 - relevanceWeight) * (h.probability ?? 0)
    ranked.sort((a, b) => blended(b) - blended(a) || b.score - a.score)
    let kept = ranked.filter((h) => (h.relevance ?? 0) >= threshold)
    if (kept.length === 0) kept = ranked.slice(0, 3)

    const result = {
      hits: kept,
      model: body.model ?? model,
      judged: cands.length,
      inputTokens: body.usage?.input_tokens ?? 0,
      answerable: body.answers.answerable?.noul ?? 0,
      tookMs: Math.round(performance.now() - started),
    }
    cache.set(key, result)
    return { ...result, cached: false }
  }

  /** Run both passes and return everything. Useful for tests and benchmarks. */
  async function search(query: string) {
    const t0 = performance.now()
    const lex = lexical(query)
    const lexicalMs = performance.now() - t0
    const jev = await judge(query, lex)
    return { lexical: lex, lexicalMs, jev }
  }

  /**
   * Fetch-API handler. GET /?q=term streams NDJSON: a `lexical` event as soon
   * as the first pass is done, then a `jev` event. Add `stream=0` to receive a
   * single JSON object with the final ranking instead.
   */
  async function handler(request: Request): Promise<Response> {
    const url = new URL(request.url)
    const query = (url.searchParams.get("q") ?? "").slice(0, 200)
    const wantsStream = url.searchParams.get("stream") !== "0"
    const headers = { "Cache-Control": "no-store" }

    if (query.trim().length === 0) {
      return Response.json({ type: "lexical", query, hits: [], tookMs: 0 } satisfies SearchEvent, { headers })
    }

    if (!wantsStream) {
      try {
        const r = await search(query)
        const event: SearchEvent = { type: "jev", query, ...r.jev }
        return Response.json(event, { headers })
      } catch (err) {
        return Response.json({ type: "error", query, message: (err as Error).message } satisfies SearchEvent, { status: 502, headers })
      }
    }

    const encoder = new TextEncoder()
    const stream = new ReadableStream<Uint8Array>({
      async start(controller) {
        const send = (e: SearchEvent) => controller.enqueue(encoder.encode(JSON.stringify(e) + "\n"))
        const t0 = performance.now()
        const lex = lexical(query)
        send({ type: "lexical", query, hits: lex, tookMs: Math.round((performance.now() - t0) * 100) / 100 })
        try {
          const jev = await judge(query, lex)
          send({ type: "jev", query, ...jev })
        } catch (err) {
          send({ type: "error", query, message: (err as Error).message })
        }
        controller.close()
      },
    })
    return new Response(stream, {
      headers: { ...headers, "Content-Type": "application/x-ndjson; charset=utf-8", "X-Accel-Buffering": "no" },
    })
  }

  return { search, lexical, judge, handler, documents }
}

/** Convenience: just the request handler. */
export function createJevSearchHandler(options: JevSearchOptions) {
  return createJevSearch(options).handler
}

